function database(empty=false){return{withTransaction:async fn=>fn({query:async(sql,params=[])=>sql.includes("external_identities identity")?[{external_identity_id:1n,player_id:10n,display_name:"조회회원",rank_emoji:"⭐"}]:sql.includes("player_title_read_delegates")?[{allowed:1}]:sql.includes("SELECT id,result_json")?[{id:77n,result_json:null}]:sql.includes("BINARY profile.current_display_name")?[{player_id:11n,display_name:"대상회원",rank_emoji:"🌙"}]:sql.includes("SELECT instance_row.id")?(empty?[]:params[0]===11n?rows.slice(0,1):rows):[],execute:async sql=>({insertId:sql.includes("outbox_messages")?88n:77n})})};}
async function invoke(message,kind,empty=false){const candidate=kind==="list"?isPlayerTitleListReadCandidate(message):isPlayerTitleInfoReadCandidate(message),normalized=kind==="list"?normalizePlayerTitleListReadDispatchMessage(message):normalizePlayerTitleInfoReadDispatchMessage(message),handlerKey=kind==="list"?"player_title_list_read":"player_title_info_read";let calls=0,result=null;if(candidate&&normalized===(kind==="list"?"/타이틀목록":"/타이틀정보")&&handlerKey===(kind==="list"?"player_title_list_read":"player_title_info_read")){calls++;result=await new PlayerTitleReadService(database(empty)).read({eventId:`wave30-${message}`,externalUserId:"tester",destinationId:"room",message});}return{candidate,normalized,handlerKey,calls,reply:result?.data??"NO_REPLY"};}
